+void View3DController::cursor_pan(Cursor &p_cursor, const Ref<InputEventWithModifiers> &p_event, const Vector2 &p_relative) {
+	float pan_speed = translation_sensitivity / 150.0;
+	if (p_event.is_valid() && navigation_scheme == NAV_SCHEME_MAYA && p_event->is_shift_pressed()) {
+		pan_speed *= 10;
+	}
+
+	Transform3D camera_transform;
+
+	camera_transform.translate_local(p_cursor.pos);
+	camera_transform.basis.rotate(Vector3(1, 0, 0), -p_cursor.x_rot);
+	camera_transform.basis.rotate(Vector3(0, 1, 0), -p_cursor.y_rot);
+	Vector3 translation(
+			(invert_x_axis ? -1 : 1) * -p_relative.x * pan_speed,
+			(invert_y_axis ? -1 : 1) * p_relative.y * pan_speed,
+			0);
+	translation *= p_cursor.distance / DISTANCE_DEFAULT;
+	camera_transform.translate_local(translation);
+	p_cursor.pos = camera_transform.origin;
+}
