+		float y_rot_snapped = Math::snapped(p_cursor.unsnapped_y_rot, snap_angle);
+
+		float x_dist = Math::abs(p_cursor.unsnapped_x_rot - x_rot_snapped);
+		float y_dist = Math::abs(p_cursor.unsnapped_y_rot - y_rot_snapped);
