+	Vector3 prev_pos = prev_camera_transform.xform(Vector3(0, 0, 0));
+	Vector3 diff = prev_pos - pos;
+	p_cursor.pos += diff;
+
+	set_view_type(VIEW_TYPE_USER);
+}
